package render

import (
	"bytes"
	"encoding/json"
	"fmt"
	"path"
	"strings"

	"github.com/pelletier/go-toml/v2"

	"github.com/xxddccaa/akey/internal/spec"
)

// header is written at the top of every generated file whose format allows
// comments (TOML, JSONC). Plain JSON files have no header.
var header = []string{
	"Generated by akey from your master config. Do not edit by hand:",
	"this file is overwritten on every `akey pull`. Change master.yaml instead",
	"(`akey edit`), using tools.<tool>.extra for tool-specific settings.",
}

func renderTool(m *spec.Master, tool string) ([]File, error) {
	if !spec.IsTool(tool) {
		return nil, fmt.Errorf("render: unknown tool %q", tool)
	}
	t := m.Tools[tool]
	if t == nil {
		return nil, fmt.Errorf("render %s: no tools.%s section in master config", tool, tool)
	}
	def := m.ModelByID(t.DefaultModel)
	if def == nil {
		return nil, fmt.Errorf("render %s: default_model %q not found", tool, t.DefaultModel)
	}
	if !m.ModelAllowedFor(def, tool) {
		return nil, fmt.Errorf("render %s: default_model %q is not usable by %s", tool, def.ID, tool)
	}

	var (
		files []File
		err   error
	)
	switch tool {
	case spec.ToolCodex:
		files, err = renderCodex(m, t, def)
	case spec.ToolXdcode:
		files, err = renderXdcode(m, t, def)
	case spec.ToolClaude:
		files, err = renderClaude(m, t, def)
	case spec.ToolOpencode:
		files, err = renderOpencode(m, t, def)
	case spec.ToolPi:
		files, err = renderPi(m, t, def)
	}
	if err != nil {
		return nil, fmt.Errorf("render %s: %w", tool, err)
	}

	extra, err := extraFiles(t, files)
	if err != nil {
		return nil, fmt.Errorf("render %s: %w", tool, err)
	}
	files = append(files, extra...)

	secrets := m.Secrets()
	for i := range files {
		files[i].Tool = tool
		files[i].Mode = 0o644
		for _, s := range secrets {
			if bytes.Contains(files[i].Content, []byte(s)) {
				files[i].Mode = 0o600
				break
			}
		}
	}
	return files, nil
}

// extraFiles turns tools.<tool>.files into Files, sorted by path. Paths must
// be relative, slash-separated, without "..", and must not collide with a
// generated file.
func extraFiles(t *spec.Tool, generated []File) ([]File, error) {
	taken := map[string]bool{}
	for _, f := range generated {
		taken[f.RelPath] = true
	}
	var out []File
	for _, p := range sortedKeys(t.Files) {
		if err := checkRelPath(p); err != nil {
			return nil, fmt.Errorf("files: %w", err)
		}
		if taken[p] {
			return nil, fmt.Errorf("files: %q collides with a generated file (use extra instead)", p)
		}
		out = append(out, File{RelPath: p, Content: []byte(t.Files[p])})
	}
	return out, nil
}

func checkRelPath(p string) error {
	switch {
	case p == "":
		return fmt.Errorf("empty file path")
	case strings.Contains(p, `\`):
		return fmt.Errorf("%q: use forward slashes", p)
	case strings.HasPrefix(p, "/"), len(p) >= 2 && p[1] == ':':
		return fmt.Errorf("%q: absolute paths are not allowed", p)
	}
	for _, seg := range strings.Split(p, "/") {
		if seg == ".." {
			return fmt.Errorf("%q: \"..\" is not allowed", p)
		}
	}
	if path.Clean(p) != p || p == "." {
		return fmt.Errorf("%q: path is not clean (want %q)", p, path.Clean(p))
	}
	return nil
}

// ---------------------------------------------------------------------------
// Encoders. Map keys are sorted by both encoders, so output is deterministic.

func encodeTOML(doc map[string]any) ([]byte, error) {
	var buf bytes.Buffer
	for _, l := range header {
		buf.WriteString("# " + l + "\n")
	}
	buf.WriteString("\n")
	b, err := toml.Marshal(doc)
	if err != nil {
		return nil, err
	}
	buf.Write(b)
	return buf.Bytes(), nil
}

// encodeJSON writes 2-space indented JSON. With comment=true a JSONC header
// is prepended (only for formats that accept comments, e.g. opencode.jsonc).
func encodeJSON(doc any, comment bool) ([]byte, error) {
	var buf bytes.Buffer
	if comment {
		for _, l := range header {
			buf.WriteString("// " + l + "\n")
		}
	}
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	enc.SetIndent("", "  ")
	if err := enc.Encode(doc); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

// ---------------------------------------------------------------------------
// Shared helpers.

// splitProviderID is the provider id used by tools that need one provider
// entry per API family (opencode, pi). A master provider that has both an
// openai and an anthropic endpoint becomes "<id>" (openai) and
// "<id>-anthropic" (anthropic); single-endpoint providers keep "<id>".
func splitProviderID(m *spec.Master, md *spec.Model) string {
	p := m.Providers[md.Provider]
	if md.API == spec.APIAnthropic && p != nil && p.OpenAI != nil {
		return md.Provider + "-anthropic"
	}
	return md.Provider
}

// checkSplitCollisions rejects masters where a generated "<id>-anthropic"
// collides with a real provider id.
func checkSplitCollisions(m *spec.Master, models []*spec.Model) error {
	for _, md := range models {
		id := splitProviderID(m, md)
		if id != md.Provider && m.Providers[id] != nil {
			return fmt.Errorf("provider %q has both endpoints, so its anthropic side is named %q, which collides with an existing provider", md.Provider, id)
		}
	}
	return nil
}

// anthropicRoot normalizes an Anthropic base URL to the form used by
// ANTHROPIC_BASE_URL and the Anthropic SDKs (no trailing "/v1").
func anthropicRoot(u string) string {
	u = strings.TrimRight(u, "/")
	return strings.TrimSuffix(u, "/v1")
}

// modelEffort is the default effort to configure for a catalog entry: the
// tool-level effort for the tool's default model, else the model's own.
func modelEffort(m *spec.Master, tool string, def, md *spec.Model) string {
	if md == def {
		return m.Effort(tool)
	}
	return md.DefaultEffort
}

func hasString(ss []string, s string) bool {
	for _, x := range ss {
		if x == s {
			return true
		}
	}
	return false
}

// filterInput keeps only the input modalities a tool understands, in the
// order given by allowed.
func filterInput(in []string, allowed ...string) []any {
	var out []string
	for _, a := range allowed {
		if hasString(in, a) {
			out = append(out, a)
		}
	}
	return strList(out)
}
